  function mount(){if(location.pathname==='/pesanan'){portal();return}if(location.pathname!=='/cart')return;const host=document.querySelector('#app .summary');if(!host||host.querySelector('#rentcamOrderForm'))return;host.querySelector('.wide')?.remove();host.insertAdjacentHTML('beforeend',checkoutMarkup());update(host.querySelector('form'))}
  function resetMember(f,message='Masukkan nomor yang terdaftar di Master Customer.'){delete f.dataset.memberVerified;delete f.dataset.member;const card=f.querySelector('[data-member-card]');card.hidden=true;card.innerHTML='';const status=f.querySelector('[data-member-status]');status.className='rc-member-status';status.textContent=message}
  function update(f){if(!f)return;const member=f.elements.customer_type?.value==='member',memberPanel=f.querySelector('[data-member-panel]'),guestPanel=f.querySelector('[data-guest-panel]');if(memberPanel){memberPanel.hidden=!member;guestPanel.hidden=member;f.elements.member_phone.required=member;for(const name of ['guest_name','guest_phone'])f.elements[name].required=!member}if(f.elements.mode){const delivery=f.elements.mode.value==='delivery',collect=f.elements.return_mode.value==='collect';for(const [sel,field,on]of [['[data-delivery]','deliver_at',delivery],['[data-collect]','collect_at',collect],['[data-address]','address',delivery||collect]]){f.querySelector(sel).hidden=!on;f.elements[field].required=on}f.elements.end.min=f.elements.start.value;const days=Math.round((new Date(f.elements.end.value)-new Date(f.elements.start.value))/86400000)+1;f.querySelector('[data-estimate]').textContent=days>0?days+' hari':'Periksa tanggal'}const b=banks().find(b=>b.id===f.elements.bank?.value),info=f.querySelector('[data-bank-info]');if(info)info.textContent=b?b.bank+' · '+b.number+' · a.n. '+b.holder:banks().length?'Pilih rekening tujuan.':'Rekening belum diatur; tim akan mengonfirmasi pembayaran.';const submit=f.querySelector('.rc-submit');if(submit&&!submit.dataset.busy){const allowed=!member||Boolean(f.dataset.memberVerified);submit.disabled=!allowed;submit.querySelector('[data-submit-hint]').textContent=allowed?'Data akan diperiksa admin':'Verifikasi nomor member dahulu'}}
  async function checkMember(f){const button=f.querySelector('#rcMemberCheck'),status=f.querySelector('[data-member-status]'),phone=cleanPhone(f.elements.member_phone.value);resetMember(f,'Memeriksa nomor...');if(!/^62[0-9]{7,14}$/.test(phone)){status.className='rc-member-status error';status.textContent='Nomor HP belum valid.';update(f);return}button.disabled=true;button.textContent='Mengecek...';try{const member=await rpc('rentcam_member_lookup',{p_phone:phone});if(!member?.found)throw Error('Nomor belum terdaftar. Pilih Non-member untuk melanjutkan.');f.dataset.memberVerified=phone;f.dataset.member=JSON.stringify(member);status.className='rc-member-status success';status.textContent='Nomor terverifikasi.';const card=f.querySelector('[data-member-card]');card.hidden=false;card.innerHTML=`<span class="rc-member-icon">✓</span><div><small>MEMBER DITEMUKAN</small><strong>${E(member.name)}</strong>${member.email?`<span>${E(member.email)}</span>`:''}</div>`}catch(err){status.className='rc-member-status error';status.textContent=err.message}finally{button.disabled=false;button.textContent='Cek nomor';update(f)}}
  document.addEventListener('input',e=>{const f=e.target.closest('#rentcamOrderForm');if(f&&e.target.name==='member_phone'&&f.dataset.memberVerified&&cleanPhone(e.target.value)!==f.dataset.memberVerified){resetMember(f);update(f)}});
  document.addEventListener('change',e=>{const f=e.target.closest('.rc-form');if(f)update(f)});
  document.addEventListener('click',e=>{const b=e.target.closest('#rcMemberCheck');if(b)checkMember(b.closest('form'))});
  document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('#rentcamOrderForm [name=member_phone]')){e.preventDefault();checkMember(e.target.form)}});
  document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('#rentcamOrderForm,#rcProofForm'))return;e.preventDefault();const btn=f.querySelector('[type=submit]'),msg=f.querySelector('[data-msg]');if(btn.disabled)return;btn.disabled=true;btn.dataset.busy='1';msg.textContent='Memproses...';try{const x=Object.fromEntries(new FormData(f)),file=f.elements.receipt.files[0];if(file&&(!x.bank||Number(x.amount)<=0))throw Error('Pilih rekening dan isi nominal transfer.');if(f.id==='rcProofForm'){if(!x.bank||!file||Number(x.amount)<=0)throw Error('Lengkapi rekening, nominal dan bukti transfer.');const[id,token]=location.hash.slice(1).split(':'),sig=JSON.stringify([id,x.bank,x.amount,file.name,file.size,file.lastModified]);let pending=JSON.parse(sessionStorage.getItem('rc_proof_retry')||'null');if(pending?.sig!==sig){pending={sig,path:await upload(file)};sessionStorage.setItem('rc_proof_retry',JSON.stringify(pending))}await rpc('rentcam_customer_proof',{p_order:id,p_customer:token,p_path:pending.path,p_bank:x.bank,p_amount:Number(x.amount)});sessionStorage.removeItem('rc_proof_retry');await portal(true);return}const isMember=x.customer_type==='member';let customer;if(isMember){const phone=cleanPhone(x.member_phone);if(!f.dataset.memberVerified||phone!==f.dataset.memberVerified||!f.dataset.member)throw Error('Cek dan verifikasi nomor member dahulu.');const saved=JSON.parse(f.dataset.member);customer={name:saved.name,phone,email:saved.email||''}}else{customer={name:String(x.guest_name||'').trim(),phone:cleanPhone(x.guest_phone),email:String(x.guest_email||'').trim()};if(customer.name.length<2)throw Error('Isi nama lengkap.')}if(!/^62[0-9]{7,14}$/.test(customer.phone))throw Error('Isi WhatsApp yang valid.');const items=JSON.parse(localStorage.getItem('bsm_cart_cm')||'[]');if(!items.length)throw Error('Keranjang kosong.');if(x.end<x.start)throw Error('Tanggal selesai tidak boleh sebelum mulai.');const base={p_name:customer.name,p_phone:customer.phone,p_email:customer.email,p_start:x.start,p_end:x.end,p_notes:String(x.notes||'').trim(),p_items:items.map(i=>({id:i.id,q:i.q})),p_details:{customer_type:isMember?'member':'guest',delivery:{mode:x.mode,return_mode:x.return_mode,address:x.address||'',deliver_at:x.mode==='delivery'?new Date(x.deliver_at+'+07:00').toISOString():null,collect_at:x.return_mode==='collect'?new Date(x.collect_at+'+07:00').toISOString():null},bank_id:x.bank,transfer_amount:Number(x.amount)||null}},sig=JSON.stringify([base,file&&[file.name,file.size,file.lastModified]]);let retry=JSON.parse(sessionStorage.getItem('rentcam_order_retry')||'null');if(retry?.signature!==sig||!retry.payload){base.p_id=crypto.randomUUID();base.p_details.customer_token=crypto.randomUUID();if(file)base.p_details.receipt_path=await upload(file);retry={signature:sig,payload:base};sessionStorage.setItem('rentcam_order_retry',JSON.stringify(retry))}const order=await rpc('rentcam_checkout',retry.payload),link='/pesanan#'+order.id+':'+order.customer_token;sessionStorage.removeItem('rentcam_order_retry');localStorage.setItem('bsm_cart_cm','[]');try{cart.splice(0,cart.length);save()}catch{}localStorage.setItem('rentcam_last_order',link);f.innerHTML=`<div class="rc-order-success"><span>✓</span><h3>Pesanan berhasil dikirim</h3><p>${E(order.order_number)} · ${M(order.total)}</p><p>${file?'Bukti transfer menunggu verifikasi admin.':'Menunggu pembayaran dan konfirmasi admin.'}</p><a class="wide" href="${E(link)}">Lihat status pesanan</a><small>Simpan tautan ini untuk memantau pesanan.</small></div>`}catch(err){msg.textContent=err.message;delete btn.dataset.busy;btn.disabled=false;update(f)}});
